CREATE TABLE client_receipt_allocations (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,receipt_id BIGINT UNSIGNED NOT NULL,client_progress_statement_id BIGINT UNSIGNED NOT NULL,allocated_amount DECIMAL(18,2) NOT NULL,statement_code_snapshot VARCHAR(30) NOT NULL,statement_number_snapshot VARCHAR(100) NULL,statement_sequence_snapshot INT UNSIGNED NOT NULL,statement_date_snapshot DATE NOT NULL,statement_amount_snapshot DECIMAL(18,2) NOT NULL,allocated_at DATETIME NOT NULL,allocated_by BIGINT UNSIGNED NOT NULL,notes TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_client_receipt_allocations_receipt(receipt_id,id),KEY idx_client_receipt_allocations_statement(client_progress_statement_id,id),CONSTRAINT fk_client_receipt_allocations_receipt FOREIGN KEY(receipt_id) REFERENCES client_receipts(id) ON DELETE RESTRICT,CONSTRAINT fk_client_receipt_allocations_statement FOREIGN KEY(client_progress_statement_id) REFERENCES client_progress_statements(id) ON DELETE RESTRICT,CONSTRAINT fk_client_receipt_allocations_user FOREIGN KEY(allocated_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT chk_client_receipt_allocation_amount CHECK(allocated_amount>0),CONSTRAINT chk_client_receipt_statement_amount CHECK(statement_amount_snapshot>0),CONSTRAINT chk_client_receipt_statement_sequence CHECK(statement_sequence_snapshot>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
